	 * Writes bytes from binData to the currently open file. offset selects the starting byte within the BinData; numBytes selects how many bytes to write. Set both to 0 to write the entire BinData, or set numBytes to 0 to write all remaining bytes beginning at offset.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkFileAccessRef.html#FileWriteBd
	 * @param CkBinData $binData
	 * @param int $offset
	 * @param int $numBytes
	 * @return bool
	 */
	function FileWriteBd($binData,$offset,$numBytes) {
		return CkFileAccess_FileWriteBd($this->_cPtr,$binData,$offset,$numBytes);
	}

	/**
	 * Generates a fixed-width decimal block identifier from index, padded to length characters, and then encodes those bytes using encoding (for example base64, hex, or ascii). This utility was originally added for block-oriented uploads such as Azure Blob block uploads. Ordering: Fixed-width decimal identifiers preserve numeric ordering when identifiers are compared lexically, provided the chosen width is large enough for all indexes.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkFileAccessRef.html#GenBlockId
	 * @param int $index
	 * @param int $length
	 * @param ?string $encoding
	 * @return ?string
	 */
	function genBlockId($index,$length,$encoding) {
		return CkFileAccess_genBlockId($this->_cPtr,$index,$length,$encoding);
	}

	/**
	 * Returns the directory portion of path according to Chilkat path-parsing rules. GetDirectoryName('C:\MyDir\MySubDir\myfile.ext')  ->  'C:\MyDir\MySubDir\' GetDirectoryName('C:\MyDir\MySubDir')             ->  'C:\MyDir\' GetDirectoryName('C:\')                             ->  'C:\'
	 * @see https://www.chilkatsoft.com/refdoc/phpCkFileAccessRef.html#GetDirectoryName
	 * @param ?string $path
	 * @return ?string
	 */
	function getDirectoryName($path) {
		return CkFileAccess_getDirectoryName($this->_cPtr,$path);
	}

	/**
	 * Returns the directory portion of path according to Chilkat path-parsing rules. GetDirectoryName('C:\MyDir\MySubDir\myfile.ext')  ->  'C:\MyDir\MySubDir\' GetDirectoryName('C:\MyDir\MySubDir')             ->  'C:\MyDir\' GetDirectoryName('C:\')                             ->  'C:\'
	 * @see https://www.chilkatsoft.com/refdoc/phpCkFileAccessRef.html#GetDirectoryName
	 * @param ?string $path
	 * @return ?string
	 */
	function directoryName($path) {
		return CkFileAccess_directoryName($this->_cPtr,$path);
	}

	/**
	 * Returns the filename extension portion of path, including the leading period. A period appearing only in a directory name is not treated as the file extension. GetExtension('C:\mydir.old\myfile.ext')  ->  '.ext' GetExtension('C:\mydir.old\')            ->  ''
	 * @see https://www.chilkatsoft.com/refdoc/phpCkFileAccessRef.html#GetExtension
	 * @param ?string $path
	 * @return ?string
	 */
	function getExtension($path) {
		return CkFileAccess_getExtension($this->_cPtr,$path);
	}

	/**
	 * Returns the filename extension portion of path, including the leading period. A period appearing only in a directory name is not treated as the file extension. GetExtension('C:\mydir.old\myfile.ext')  ->  '.ext' GetExtension('C:\mydir.old\')            ->  ''
	 * @see https://www.chilkatsoft.com/refdoc/phpCkFileAccessRef.html#GetExtension
	 * @param ?string $path
	 * @return ?string
	 */
	function extension($path) {
		return CkFileAccess_extension($this->_cPtr,$path);
	}

	/**
	 * Returns the final filename component of path, including its extension. If the path ends with a directory separator, the returned filename is empty. GetFileName('C:\mydir\myfile.ext')  ->  'myfile.ext' GetFileName('C:\mydir\')            ->  ''
	 * @see https://www.chilkatsoft.com/refdoc/phpCkFileAccessRef.html#GetFileName
	 * @param ?string $path
	 * @return ?string
	 */
	function getFileName($path) {
		return CkFileAccess_getFileName($this->_cPtr,$path);
	}

	/**
	 * Returns the final filename component of path, including its extension. If the path ends with a directory separator, the returned filename is empty. GetFileName('C:\mydir\myfile.ext')  ->  'myfile.ext' GetFileName('C:\mydir\')            ->  ''
	 * @see https://www.chilkatsoft.com/refdoc/phpCkFileAccessRef.html#GetFileName
	 * @param ?string $path
	 * @return ?string
	 */
	function fileName($path) {
		return CkFileAccess_fileName($this->_cPtr,$path);
	}

	/**
	 * Returns the final filename component of path with its extension removed. If path ends with a directory separator, the returned value is empty. GetFileNameWithoutExtension('C:\mydir\myfile.ext')  ->  'myfile' GetFileNameWithoutExtension('C:\mydir\')            ->  ''
	 * @see https://www.chilkatsoft.com/refdoc/phpCkFileAccessRef.html#GetFileNameWithoutExtension
	 * @param ?string $path
	 * @return ?string
	 */
	function getFileNameWithoutExtension($path) {
		return CkFileAccess_getFileNameWithoutExtension($this->_cPtr,$path);
	}

	/**
	 * Returns the final filename component of path with its extension removed. If path ends with a directory separator, the returned value is empty. GetFileNameWithoutExtension('C:\mydir\myfile.ext')  ->  'myfile' GetFileNameWithoutExtension('C:\mydir\')            ->  ''
	 * @see https://www.chilkatsoft.com/refdoc/phpCkFileAccessRef.html#GetFileNameWithoutExtension
	 * @param ?string $path
	 * @return ?string
	 */
	function fileNameWithoutExtension($path) {
		return CkFileAccess_fileNameWithoutExtension($this->_cPtr,$path);
	}

	/**
	 * Deprecated. Use GetFileTimeStr instead. Returns one file timestamp as a CkDateTime, selected by which: 0 = last-modified, 1 = last-access, 2 = creation. Portability: Creation/birth time is not available on every filesystem. The historical Chilkat behavior documented for Linux is to return the last-modified time when creation time is unavailable.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkFileAccessRef.html#GetFileTime
	 * @param ?string $path
	 * @param int $which
	 * @return ?CkDateTime
	 * @deprecated
	 */
	function GetFileTime($path,$which) {
		return chilkat::_obj(CkFileAccess_GetFileTime($this->_cPtr,$path,$which),'CkDateTime');
	}

	/**
	 * Returns one file timestamp as an ISO 8601 UTC string in the form YYYY-MM-DDTHH:MM:SSZ. The which argument selects 0 = last-modified, 1 = last-access, or 2 = creation. Portability: Creation/birth time is not available on every filesystem. The documented Chilkat behavior on Linux is to return the last-modified time when creation time is unavailable.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkFileAccessRef.html#GetFileTimeStr
	 * @param ?string $path
	 * @param int $which
	 * @return ?string
	 */
	function getFileTimeStr($path,$which) {
		return CkFileAccess_getFileTimeStr($this->_cPtr,$path,$which);
	}

	/**
	 * Returns one file timestamp as an ISO 8601 UTC string in the form YYYY-MM-DDTHH:MM:SSZ. The which argument selects 0 = last-modified, 1 = last-access, or 2 = creation. Portability: Creation/birth time is not available on every filesystem. The documented Chilkat behavior on Linux is to return the last-modified time when creation time is unavailable.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkFileAccessRef.html#GetFileTimeStr
	 * @param ?string $path
	 * @param int $which
	 * @return ?string
	 */
	function fileTimeStr($path,$which) {
		return CkFileAccess_fileTimeStr($this->_cPtr,$path,$which);
	}

	/**
	 * Deprecated. Use GetFileTimeStr instead. Returns the last-modified date/time for path as a CkDateTime. The documented resolution of this legacy method is one second.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkFileAccessRef.html#GetLastModified
	 * @param ?string $path
	 * @return ?CkDateTime
	 * @deprecated
	 */
	function GetLastModified($path) {
		return chilkat::_obj(CkFileAccess_GetLastModified($this->_cPtr,$path),'CkDateTime');
	}

	/**
	 * Returns how many blockSize-byte blocks are required to cover the currently open file. A partial final block counts as one block. Returns 0 for an empty file and -1 if no file is open. Calculation: Conceptually this is ceil(fileSize / blockSize) for a non-empty file.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkFileAccessRef.html#GetNumBlocks
	 * @param int $blockSize
	 * @return int
	 */
	function GetNumBlocks($blockSize) {
		return CkFileAccess_GetNumBlocks($this->_cPtr,$blockSize);
	}

	/**
	 * Generates a temporary pathname in dirPath using prefix and a random alphanumeric suffix, in the general form prefix_xxxx.TMP. The returned pathname is guaranteed not to already exist at the time it is generated.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkFileAccessRef.html#GetTempFilename
	 * @param ?string $dirPath
	 * @param ?string $prefix
	 * @return ?string
	 */
	function getTempFilename($dirPath,$prefix) {
		return CkFileAccess_getTempFilename($this->_cPtr,$dirPath,$prefix);
	}

	/**
	 * Generates a temporary pathname in dirPath using prefix and a random alphanumeric suffix, in the general form prefix_xxxx.TMP. The returned pathname is guaranteed not to already exist at the time it is generated.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkFileAccessRef.html#GetTempFilename
	 * @param ?string $dirPath
	 * @param ?string $prefix
	 * @return ?string
	 */
	function tempFilename($dirPath,$prefix) {
		return CkFileAccess_tempFilename($this->_cPtr,$dirPath,$prefix);
	}

	/**
	 * Opens filePath for writing at end-of-file. The file is created if it does not exist. Existing content is preserved, and the initial file position is at the end. Open failures: If the open/create operation fails, inspect FileOpenError and FileOpenErrorMsg. On Windows, LockFileOnOpen can request exclusive access for this method.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkFileAccessRef.html#OpenForAppend
	 * @param ?string $filePath
	 * @return bool
	 */
	function OpenForAppend($filePath) {
		return CkFileAccess_OpenForAppend($this->_cPtr,$filePath);
	}

	/**
	 * Opens an existing filePath for reading. The file may contain text or binary data and must already exist. Open failures: If the open/create operation fails, inspect FileOpenError and FileOpenErrorMsg. On Windows, LockFileOnOpen can request exclusive access for this method.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkFileAccessRef.html#OpenForRead
	 * @param ?string $filePath
	 * @return bool
	 */
	function OpenForRead($filePath) {
		return CkFileAccess_OpenForRead($this->_cPtr,$filePath);
	}

	/**
	 * Opens filePath for both reading and writing. The file is created if necessary. Existing content is preserved, and the initial file position is at the beginning. Open failures: If the open/create operation fails, inspect FileOpenError and FileOpenErrorMsg. On Windows, LockFileOnOpen can request exclusive access for this method.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkFileAccessRef.html#OpenForReadWrite
	 * @param ?string $filePath
	 * @return bool
	 */
	function OpenForReadWrite($filePath) {
		return CkFileAccess_OpenForReadWrite($this->_cPtr,$filePath);
	}

	/**
	 * Opens filePath for writing. The file is created if necessary; if it already exists, it is truncated to zero length when opened. Open failures: If the open/create operation fails, inspect FileOpenError and FileOpenErrorMsg. On Windows, LockFileOnOpen can request exclusive access for this method.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkFileAccessRef.html#OpenForWrite
	 * @param ?string $filePath
	 * @return bool
	 */
	function OpenForWrite($filePath) {
		return CkFileAccess_OpenForWrite($this->_cPtr,$filePath);
	}

	/**
	 * Reads the entire file at filePath as binary data and returns an encoded textual representation. Supported encoding names documented for this method include base64, hex, qp, and url. Encoding is not encryption: These encodings transform bytes into text; they do not provide confidentiality.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkFileAccessRef.html#ReadBinaryToEncoded
	 * @param ?string $filePath
	 * @param ?string $encoding
	 * @return ?string
	 */
	function readBinaryToEncoded($filePath,$encoding) {
		return CkFileAccess_readBinaryToEncoded($this->_cPtr,$filePath,$encoding);
	}

	/**
	 * Reads the zero-based block blockIndex from the currently open file, where each block is blockSize bytes. If the final block is shorter than blockSize, only the remaining bytes are returned.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkFileAccessRef.html#ReadBlock
	 * @param int $blockIndex
	 * @param int $blockSize
	 * @param CkByteData $outBytes
	 * @return bool
	 */
	function ReadBlock($blockIndex,$blockSize,$outBytes) {
		return CkFileAccess_ReadBlock($this->_cPtr,$blockIndex,$blockSize,$outBytes);
	}

	/**
	 * Reads the zero-based block blockIndex from the currently open file, using blockSize bytes per block, and appends the bytes to bd. A partial final block is appended at its actual length. Destination behavior: Existing contents of bd are preserved; the block bytes are appended.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkFileAccessRef.html#ReadBlockBd
	 * @param int $blockIndex
	 * @param int $blockSize
	 * @param CkBinData $bd
	 * @return bool
	 */
	function ReadBlockBd($blockIndex,$blockSize,$bd) {
		return CkFileAccess_ReadBlockBd($this->_cPtr,$blockIndex,$blockSize,$bd);
	}

	/**
	 * Reads the entire file at filePath as raw bytes and returns the binary data. Memory use: The whole file is loaded into memory. For very large files, use OpenForRead together with FileReadBd or block-oriented methods.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkFileAccessRef.html#ReadEntireFile
	 * @param ?string $filePath
	 * @param CkByteData $outBytes
	 * @return bool
	 */
	function ReadEntireFile($filePath,$outBytes) {
		return CkFileAccess_ReadEntireFile($this->_cPtr,$filePath,$outBytes);
	}

	/**
	 * Reads the entire file at filePath, decodes its bytes using charset, and returns the resulting text. Charset matters: The charset controls byte-to-character conversion. Use the encoding that actually represents the file; incorrect charset selection can produce incorrect text or conversion failure.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkFileAccessRef.html#ReadEntireTextFile
	 * @param ?string $filePath
	 * @param ?string $charset
	 * @return ?string
	 */
	function readEntireTextFile($filePath,$charset) {
		return CkFileAccess_readEntireTextFile($this->_cPtr,$filePath,$charset);
	}

	/**
	 * Scans the currently open file for the next text fragment beginning with beginMarker and ending with endMarker. The matched fragment, including both markers, is decoded using charset and appended to sb. If startAtBeginning is _TRUE_, scanning restarts at the beginning of the file; otherwise it continues after the previously matched fragment. 1A fragment was found and appended. 0No matching fragment was found. -1An error occurred while reading.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkFileAccessRef.html#ReadNextFragment
	 * @param bool $startAtBeginning
	 * @param ?string $beginMarker
	 * @param ?string $endMarker
	 * @param ?string $charset
	 * @param CkStringBuilder $sb
	 * @return int
	 */
	function ReadNextFragment($startAtBeginning,$beginMarker,$endMarker,$charset,$sb) {
		return CkFileAccess_ReadNextFragment($this->_cPtr,$startAtBeginning,$beginMarker,$endMarker,$charset,$sb);
	}

	/**
	 * Reassembles a file previously divided by SplitFile. Parts are read from partsDirPath using the supplied partPrefix and partExtension, and the combined bytes are written to reassembledFilename. Byte-for-byte reconstruction: Reassembly is a binary operation; no text decoding or newline conversion is performed.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkFileAccessRef.html#ReassembleFile
	 * @param ?string $partsDirPath
	 * @param ?string $partPrefix
	 * @param ?string $partExtension
	 * @param ?string $reassembledFilename
	 * @return bool
	 */
	function ReassembleFile($partsDirPath,$partPrefix,$partExtension,$reassembledFilename) {
		return CkFileAccess_ReassembleFile($this->_cPtr,$partsDirPath,$partPrefix,$partExtension,$reassembledFilename);
	}

	/**
	 * Reads the file at filePath as text using charset, replaces occurrences of existingString with replacementString, writes the updated text back to the file, and returns the number of replacements made. Text operation: This is character-based replacement after decoding the file. It is not suitable for arbitrary binary files.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkFileAccessRef.html#ReplaceStrings
	 * @param ?string $filePath
	 * @param ?string $charset
	 * @param ?string $existingString
	 * @param ?string $replacementString
	 * @return int
	 */
	function ReplaceStrings($filePath,$charset,$existingString,$replacementString) {
		return CkFileAccess_ReplaceStrings($this->_cPtr,$filePath,$charset,$existingString,$replacementString);
	}

	/**
	 * Changes the current working directory of the calling process to dirPath. Process-wide effect: The current directory is normally process-wide, so changing it can affect relative paths used by other code or threads. Absolute paths avoid that dependency.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkFileAccessRef.html#SetCurrentDir
	 * @param ?string $dirPath
	 * @return bool
	 */
	function SetCurrentDir($dirPath) {
		return CkFileAccess_SetCurrentDir($this->_cPtr,$dirPath);
	}

	/**
	 * Sets the creation, last-access, and last-modified timestamps for filePath from the supplied CkDateTime objects. On filesystems that do not support a creation/birth time, createTime is ignored. Filesystem differences: Timestamp availability and precision are filesystem- and operating-system-dependent.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkFileAccessRef.html#SetFileTimes
	 * @param ?string $filePath
	 * @param CkDateTime $createTime
	 * @param CkDateTime $lastAccessTime
	 * @param CkDateTime $lastModTime
	 * @return bool
	 */
	function SetFileTimes($filePath,$createTime,$lastAccessTime,$lastModTime) {
		return CkFileAccess_SetFileTimes($this->_cPtr,$filePath,$createTime,$lastAccessTime,$lastModTime);
	}

	/**
	 * Sets the last-modified timestamp of filePath from lastModified. The precision actually stored depends on the underlying filesystem.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkFileAccessRef.html#SetLastModified
	 * @param ?string $filePath
	 * @param CkDateTime $lastModified
	 * @return bool
	 */
	function SetLastModified($filePath,$lastModified) {
		return CkFileAccess_SetLastModified($this->_cPtr,$filePath,$lastModified);
	}

	/**
	 * Splits fileToSplit into sequential binary parts of up to partSize bytes and writes them to destDir using partPrefix and partExtension. Use ReassembleFile to reconstruct the original file.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkFileAccessRef.html#SplitFile
	 * @param ?string $fileToSplit
	 * @param ?string $partPrefix
	 * @param ?string $partExtension
	 * @param int $partSize
	 * @param ?string $destDir
	 * @return bool
	 */
	function SplitFile($fileToSplit,$partPrefix,$partExtension,$partSize,$destDir) {
		return CkFileAccess_SplitFile($this->_cPtr,$fileToSplit,$partPrefix,$partExtension,$partSize,$destDir);
	}

	/**
	 * Creates a symbolic link at linkPath that refers to targetPath. Windows note: A Windows symbolic link is not the same as a Windows shortcut. Windows may require elevated privileges or an operating-system configuration such as Developer Mode that permits unprivileged symbolic-link creation, depending on system policy and how the application is launched.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkFileAccessRef.html#SymlinkCreate
	 * @param ?string $targetPath
	 * @param ?string $linkPath
	 * @return bool
	 */
	function SymlinkCreate($targetPath,$linkPath) {
		return CkFileAccess_SymlinkCreate($this->_cPtr,$targetPath,$linkPath);
	}

	/**
	 * Returns the resolved target pathname for the symbolic link at linkPath. On Windows, this method also understands Windows shortcut (.lnk) files and returns the absolute target path. Link vs. target: A symbolic link is a filesystem object that refers to another path. A Windows shortcut is a separate shell-file format; Chilkat supports both here even though they are different mechanisms.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkFileAccessRef.html#SymlinkTarget
	 * @param ?string $linkPath
	 * @return ?string
	 */
	function symlinkTarget($linkPath) {
		return CkFileAccess_symlinkTarget($this->_cPtr,$linkPath);
	}

	/**
	 * Recursively deletes the directory tree rooted at path, including contained files and subdirectories. Destructive operation: This operation is recursive and destructive. Ensure path identifies the intended tree before calling it.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkFileAccessRef.html#TreeDelete
	 * @param ?string $path
	 * @return bool
	 */
	function TreeDelete($path) {
		return CkFileAccess_TreeDelete($this->_cPtr,$path);
	}

	/**
	 * Truncates the currently open file at the current file position. Bytes at and after that position are removed, making the current position the new end-of-file. Use with FileSeek: A common pattern is to seek to the desired new length and then call Truncate.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkFileAccessRef.html#Truncate
	 * @return bool
	 */
	function Truncate() {
		return CkFileAccess_Truncate($this->_cPtr);
	}

	/**
	 * Creates or opens filePath, writes all bytes from fileData, and closes the file. Existing file content is replaced.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkFileAccessRef.html#WriteEntireFile
	 * @param ?string $filePath
	 * @param CkByteData $fileData
	 * @return bool
	 */
	function WriteEntireFile($filePath,$fileData) {
		return CkFileAccess_WriteEntireFile($this->_cPtr,$filePath,$fileData);
	}

	/**
	 * Creates or opens filePath, encodes textData using charset, writes the resulting bytes, and closes the file. Existing file content is replaced. If includePreamble is _TRUE_, an appropriate preamble/BOM is included for encodings such as UTF-8 or UTF-16. BOM terminology: A BOM is part of the byte representation of the text file; it is not part of the application string itself.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkFileAccessRef.html#WriteEntireTextFile
	 * @param ?string $filePath
	 * @param ?string $textData
	 * @param ?string $charset
	 * @param bool $includedPreamble
	 * @return bool
	 */
	function WriteEntireTextFile($filePath,$textData,$charset,$includedPreamble) {
		return CkFileAccess_WriteEntireTextFile($this->_cPtr,$filePath,$textData,$charset,$includedPreamble);
	}
}
